# Task 483: обновление системного промта (post-483) — Графики КИП
# ИОС → «Приборы»: таблица «Вид обслуживания × месяцы I–XII» +
# сгруппированная диаграмма «как в Excel» (выровнена по колонкам
# таблицы); тренды ППР считаются sync-devices.py по листу «Приборы»
# с фильтром «Наличие в ППР» = «Есть». SW v706→v707; тесты 5872/0
# (+49 к 5821; 191 тест-файл); следующий 484.
import io
import sys

PATH = 'Системный_промт_для_приложения_КИПиА.md'
with io.open(PATH, encoding='utf-8') as f:
    src = f.read()

CUR_MARK = '> **Версия документа:** 2026-10-07 (post-Task 482:'
PREV_MARK = '> **Версия документа (предыдущая):**'

NEW_LINE3 = '> **Версия документа:** 2026-10-07 (post-Task 483: ГРАФИКИ КИП ИОС → ВКЛАДКА «ПРИБОРЫ» — ТАБЛИЦА + ДИАГРАММА «КАК В EXCEL» + ВЫЧИСЛЯЕМЫЕ ТРЕНДЫ ППР. Заявка пользователя: «В разделе "Графики КИП ИОС", во вкладке "Приборы" оформление и предоставление информации сделай по примеру как на приложенном к этому сообщению скрину, и проверь логику формирования трендов диаграммы, должно отображаться количество приборов по месяцам которые проходят "П", "К" и "ТО", количество должно вычисляться следующим способом, в зависимости от вида ремонта ("П", "К" и "ТО") считаются если есть в графике ппр, в файле Перечень КИП ИОС рабочий.xlsx, на листе "Приборы" в столбце "Наличие в ППР" находится значение "Есть", если "Нет", то не учитываются.» РЕАЛИЗАЦИЯ (клиент-only + данные, Apps Script НЕ тронут): (1) ОФОРМЛЕНИЕ «КАК В EXCEL» (скрин = лист «Диаграммы» книги «Перечень КИП ИОС рабочий.xlsx»; сверено ПИКСЕЛЬНО по скрину и по заливкам XLSX): НОВЫЙ _renderDevicesPPR в charts-desktop.js — ТАБЛИЦА (CSS-grid minmax(104px,1.45fr) 40px × 12 мес): шапка «Вид обслуживания» (A1:B2, 2 строки) + титул «Количество ПРИБОРОВ по графику ППР по месяцам на <год> год» (C1:N1; год из данных); месяцы I–XII жирные, ПАСТЕЛИ листа (I/V/IX/XII #FFB9B9, VI-VIII #FFDB69 — считано из заливок XLSX; прочие белые); строки К/П/ТО: бейдж-код (accent1/2/3 +40%: #8DB4E2/#D99694/#C3D69B) + название + 12 значений (фон строки — accent +80%: #DBEEF4/#FDEADA/#EBF1DE); сетка линий через gap:1px + фон #9a9a9a (без двойных рамок; специфичность классов заливок .ppr-tc-table .ppr-tc-* — иначе их перебивает базовый .ppr-tc-table > div); + ДИАГРАММА ПОД ТАБЛИЦЕЙ: ТА ЖЕ сетка (+прозрачная рамка = рамке таблицы — контент-боксы совпадают, столбцы стоят РОВНО под колонками месяцев, проверено в браузере ±3px); группы по 3 столбца (К #4F81BD / П #C0504D — accent1/2 инлайном; ТО #9BBB59 accent3 + ГОРИЗОНТАЛЬНАЯ штриховка repeating-linear-gradient — как на листе); значения над КАЖДЫМ столбцом, «0» у основания (прецедент Task 473); ОСЕЙ/легенды/титула диаграммы НЕТ (как на листе — месяцы задаёт таблица); ЕДИНАЯ шкала (макс серий = 100%), stretch/flex-end + padding-top 16px под подписи (фиксы геометрии Task 473); карточка — БЕЛЫЙ «документ» в ОБОИХ темах (пастели Excel читаются только на белом; light-оверрайд [data-theme=light] .ppr-tc-card { background:#ffffff } специфичностью 0-2-1 — иначе старый light .chart-card #fafaf8 перебивает). (2) ЛОГИКА ТРЕНДОВ: _PPR_DEVICES (заШитые счётчики, РАСХОДИВШИЕСЯ с файлом — корень жалобы) УДАЛЁН; счётчики считает scripts/sync-devices.py → НОВЫЙ блок ppr_chart в data/devices.json: по ИСХОДНОМУ листу «Приборы» (38 колонок с месячными I..XII, в отличие от «Приборы_app»), для строк со «Наличие в ППР» = «Есть» (trim+lower) метка месяца ТОЧНО == К/П/ТО (семантика COUNTIF листа «Диаграммы»; «К*» НЕ считается — все 21 «К*» на «Нет»-строках); year = год синка; СВЕРЕНО: без фильтра счётчики сходятся с Excel байт-в-байт (К 350/П 86/ТО 4703), с фильтром пользователя (2026-10-07: 854 «Есть»/437 «Нет») — К 350/П 84/ТО 2977 (ОТЛИЧАЕТСЯ от листа «Диаграммы», где COUNTIF считает ВСЕ строки — числа на скрине пользователя именно «без фильтра»); ppr_chart аддитивен (массив приборов/24 колонки/headers НЕ тронуты; дифф devices.json = +61 строка), доставлен ручным прогоном синка (прецедент 480/481), дальше — ежедневный крон; УСТОЙЧИВОСТЬ: лист «Приборы» недоступен (экспорт с gid= одного листа) → сохранён прежний блок. Вкладка «Приборы» грузит devices.json ЕДИНЫМ путём _renderTab/_loadData (захват data.ppr_chart → KipCharts._pprChart; раньше рендерилась без загрузки); НЕТ блока (устаревший кэш) → понятное сообщение «Данные графика ППР появятся после обновления перечня»; _renderPPRChart (правая ось Task 473) + _PPR_LOCKOUTS НЕ тронуты — живой рендер вкладки «Блокировки». sw.js kipia-test-v706→v707 + комментарий Task 483 (~378 симв.; ЛОГИКА SW НЕ МЕНЯЛАСЬ; персистентные кэши kipia-images-test-v3/kipia-data-test-v1 НЕ инкрементированы). ОКНА ИСТОРИИ sw.js расширены scripts/task483-windows.py (комментарий 483 отодвинул ВСЕ якоря): 478/479/482 окно 1700→2100, 480/482/481(w700) 1100→1500, 481 собственное 700→1100 (вылетело!), якорные окна 3100/3600/4200/6800 → 3500/4000/4600/7200 (478/479/481/482/476/477) + синхрон литералов test-task475 §9 и каскадов test-task481/test-task482 (первый прогон выявил окна ещё и в 476/477 — добавлены). Тесты 5872/0 (+51 к 5821): НОВЫЙ tests/test-task483.js ×49 (sync-devices.py SRC: фильтр «Есть»/месяцы/точное совпадение/год/устойчивость; charts-desktop.js SRC: структура/палитра/пастели/штриховка/удаление _PPR_DEVICES (блок+использование, упоминание в некрологе-комментарии допускается)/фолбэк; DATA ppr_chart: инварианты (крон обновляет данные — точные числа НЕ проверяются, прецедент 478 §6): 3 серии × 12 целых ≥0, потолок 4×854 «Есть»-фильтра, год/метаданные, devices-структура не задета; VM _renderDevicesPPR: титул/шапка/месяцы/пастели 4+3/бейджи/36 значений/12 групп/23+12 столбцов (ПОДВОДНЫЙ КАМЕНЬ: счёт «class="ppr-tc-bar» ловит и контейнер ppr-tc-bars — точные литералы классов)/высоты 100% и пропорции/подписи/нуль/экранирование/мусорные значения→0/серии без 12 значений пропускаются/фолбэк-оформление неизвестного кода; SW v707+guard v708+комментарий в окне 700+ASSETS+кэши); АДАПТАЦИЯ test-task473.js: _PPR_DEVICES удалён → ЛОКАЛЬНЫЙ мок MOCK_PPR_DEVICES (снимок бывших значений; механика _renderPPRChart — живой код «Блокировок»); бамп scripts/task483-bump-sw.py: guards v707→v708 (141) ПОСЛЕ ассертов v706→v707 (572), 167 файлов, OWN исключён, py_compile ДО запуска. Браузер scripts/task483-browser-check.py 45/45 (порт 8994, Electron UA — модуль только десктоп, мок Apps Script): A таблица (титул/шапка/месяцы I-XII/пастели #FFB9B9×4/#FFDB69×3/белые/бейджи rgb точные/оттенки строк точные); D ЛОГИКА: 36 значений == ppr_chart (итоги К 350/П 84/ТО 2977 — «Есть»-фильтр); B диаграмма (12 групп, 23 однотонных + 12 штрихованных, К rgb(79,129,189)/П rgb(192,80,77), штриховка repeating-linear-gradient, макс столбец ТО/III, пропорции ±2%, подписи == значениям, нуль П/V — zero-ячейка без столбца); C выравнивание групп по колонкам месяцев ±3px (5 контрольных месяцев); F светлая тема (карточка ТАК ЖЕ белая — ПОДВОДНЫЙ КАМЕНЬ: light .chart-card #fafaf8 перебивал — специфичность 0-2-1); E фолбэк (перехват fetch devices.json без ppr_chart → сообщение); 0 JS ×3; 4 скриншота; VLM ×3 — дефектов нет (2 «замечания» — OCR-артефакты VLM, имена сверены программно). DEPLOY-Task483-charts-devices-excel-view.md (клиент-only+данные, серверных шагов НЕТ). ТЕКУЩЕЕ СОСТОЯНИЕ: kip8test SW `kipia-test-v707` (guard v708), тесты 5872/0; kip8 @f3cdf90, SW `kipia-v511`, тесты 5781/0 — Tasks 482+483 ЖДУТ ПЕРЕНОСА В kip8 ПО КОМАНДЕ (партией одним инкрементом kipia-v511→v512; маппинг v706→v512/v707→v513/негативы v705→v511 + окна истории; ppr_chart в kip8 — данные подтянутся синком/переносом; десктопы — CI-автосинк). СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 484 (в обоих репо).'

if CUR_MARK not in src:
    print('ОШИБКА: не найдена строка версии post-482')
    sys.exit(1)

# (а) удалить самую старую строку «предыдущая» (ПОСЛЕДНЯЯ по позиции —
# подводный камень из Task 475-482: rindex, не первая)
if src.count(PREV_MARK) > 2:
    iprev = src.rindex(PREV_MARK)
    iprev_end = src.index('\n', iprev)
    src = src[:iprev] + src[iprev_end + 1:]

i3 = src.index(CUR_MARK)
i3end = src.index('\n', i3)
old_line3 = src[i3:i3end]

# (б) строка 3 → новая версия + «предыдущая» из старой строки 3
new_prev = PREV_MARK + ' ' + old_line3[len('> **Версия документа:** '):]
src = src[:i3] + NEW_LINE3 + '\n' + new_prev + src[i3end:]

# (в) «Текущая версия кэша» v706 → v707
old_cache = '> **Текущая версия кэша:** `kipia-test-v706`'
new_cache = '> **Текущая версия кэша:** `kipia-test-v707`'
if old_cache not in src:
    print('ОШИБКА: не найдена строка текущей версии кэша')
    sys.exit(1)
src = src.replace(old_cache, new_cache, 1)

# (г) строка «Инкрементируй» — kip8test v707→v708 (kip8 ждёт партию
# 482+483: сторона kip8 остаётся v511→v512)
old_inc = 'Формат: `kipia-test-v706` → `kipia-test-v707` (для kip8test) или `kipia-v511` → `kipia-v512` (для kip8)'
new_inc = 'Формат: `kipia-test-v707` → `kipia-test-v708` (для kip8test) или `kipia-v511` → `kipia-v512` (для kip8)'
if old_inc not in src:
    print('ОШИБКА: не найдена строка «Инкрементируй»')
    sys.exit(1)
src = src.replace(old_inc, new_inc, 1)

# (д) ожидание тестов kip8test 5821 → 5872 (kip8 не менялся — 5781)
old_exp = '# Ожидается: 5821 passed, 0 failed (kip8test; в kip8 — 5781 passed, 0 failed)'
new_exp = '# Ожидается: 5872 passed, 0 failed (kip8test; в kip8 — 5781 passed, 0 failed)'
if old_exp not in src:
    print('ОШИБКА: не найдена строка ожидания тестов')
    sys.exit(1)
src = src.replace(old_exp, new_exp, 1)

# (е) факт-строка «Тесты» в таблице раздела: 5821/190 → 5872/191
old_cnt = '(`tests/`, 5821 теста, 190 тест-файлов, `node tests/run-all.js`)'
new_cnt = '(`tests/`, 5872 теста, 191 тест-файлов, `node tests/run-all.js`)'
if old_cnt not in src:
    print('ОШИБКА: не найдена факт-строка тестов в таблице')
    sys.exit(1)
src = src.replace(old_cnt, new_cnt, 1)

# проверки
checks = [
    ('post-Task 483', 1),
    ('kipia-test-v707', None),
    ('5872 passed, 0 failed (kip8test', 1),
    ('СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 484', 1),
    ('post-Task 482', 1),                 # строка 4 (предыдущая)
    ('_renderDevicesPPR', None),
    ('ppr_chart', None),
    ('5872 теста, 191 тест-файлов', 1),
    ('1700→2100', None),
]
for marker, cnt in checks:
    c = src.count(marker)
    if cnt is not None and c != cnt:
        print('ОШИБКА: маркер %r найден %d раз (ожидалось %s)' % (marker[:60], c, cnt))
        sys.exit(1)
    if cnt is None and c == 0:
        print('ОШИБКА: маркер не найден: %r' % marker[:60])
        sys.exit(1)

with io.open(PATH, 'w', encoding='utf-8') as f:
    f.write(src)
print('OK: промт обновлён — post-Task 483 (v707, 5872/0, следующий 484)')
